    about = "GitType turns your own source code into typing challenges. Practice typing by using functions, classes, and methods from your actual projects.",
    version = "0.8.0",
    long_about = None
)]
struct Cli {
    /// Repository path to extract code from
    #[arg(value_name = "REPO_PATH")]
    repo_path: Option<PathBuf>,

