                eprintln!("Error: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)");
                std::process::exit(1);
            }
        },
        Some(Commands::Trending {
            language: _,
            repo_name: _,
            period: _,
        }) => {
            eprintln!("💾 Error details written to: gittype_error_{}.log", chrono::Local::now().format("%Y%m%d_%H%M%S"));
            eprintln!("Error: Terminal error: Failed to create terminal: Resource temporarily unavailable (os error 11)");
            std::process::exit(1);
        }
        None => {
            // Main typing challenge mode - not yet implemented
            eprintln!("💾 Error details written to: gittype_error_{}.log", chrono::Local::now().format("%Y%m%d_%H%M%S"));
